// Temporary draft-only validator fixture for #499. NEVER invoke or deploy.
import {db} from 'hatchable';
export async function issue499ValidatorProbe() {
  await db.query('SELECT id FROM issue499_missing_physical');
  await db.query('WITH issue499_simple AS (SELECT 17 AS marker) SELECT marker FROM issue499_simple');
  await db.query('WITH issue499_materialized AS MATERIALIZED (SELECT 17 AS marker), issue499_dependent AS NOT MATERIALIZED (SELECT marker+1 AS marker FROM issue499_materialized) SELECT p.marker,q.marker AS next FROM issue499_materialized p CROSS JOIN issue499_dependent q');
  await db.query('WITH issue499_outer AS (SELECT 17 AS marker) SELECT n.marker FROM (WITH issue499_inner AS (SELECT marker FROM issue499_outer) SELECT marker FROM issue499_inner) n JOIN issue499_outer o ON n.marker=o.marker');
  await db.query("WITH issue499_moved AS (UPDATE brain_tasks SET status=status WHERE false RETURNING id), issue499_receipt AS (SELECT id FROM issue499_moved) SELECT m.id FROM (issue499_moved m JOIN issue499_receipt r ON m.id=r.id)");
  await db.query('WITH "Issue499Quoted" AS (SELECT 17 AS marker) SELECT marker FROM "Issue499Quoted"');
  await db.query('WITH RECURSIVE issue499_recursive(n) AS (VALUES (1) UNION ALL SELECT n+1 FROM issue499_recursive WHERE n<3) SELECT n FROM issue499_recursive');
}

